let state;
const money = (n) => n.toLocaleString("en-US", { style: "currency", currency: "EUR" });
const render = () => {
  const entries = state.data.entries;
  const chart = document.querySelector("[data-hook=chart]");
  if (entries.length === 0) chart.replaceChildren();
