  document.querySelector("[data-hook=total]").textContent = money(entries.reduce((sum, e) => sum + e.amount, 0));
  const food = entries.find((e) => e.name.toLowerCase() === "food");
  const total = entries.reduce((sum, e) => sum + e.amount, 0);
  document.getElementById("whatif").textContent = food
    ? "If food were 20% less: food " + money(food.amount * 0.8) + ", total " + money(total - food.amount * 0.2) + "."
    : "";
};
const load = () => tessera.call("data.read").then((read) => { state = read; render(); });
load();
